def resolve(case):
    nature = case['nature']
    if nature == 'WILD':
        if case.get('wounded') and not case.get('captured'):
            return 'NO_OWNER_UNDER_CONFIRMED_RULE'
        if case.get('captured') and not case.get('escaped'):
            return case['original_owner'] + '_OWNS_IN_CUSTODY'
        natural_freedom = (not case.get('visible', True)) or (not case.get('pursuit_easy', True))
        if case.get('escaped') and natural_freedom:
            return case['first_occupant'] + '_OWNS_AS_FIRST_OCCUPANT'
        return case['original_owner'] + '_RETAINS'
    if nature == 'BEE':
        if case.get('settled_on_tree') and not case.get('enclosed'):
            return 'NO_OWNER_UNTIL_HIVE'
        if case.get('escaped'):
            if case.get('visible', False) and case.get('pursuit_easy', False):
                return case['original_owner'] + '_RETAINS_SWARM'
            return case['first_occupant'] + '_OWNS_AS_FIRST_OCCUPANT'
        if case.get('enclosed'):
            return case['encloser'] + '_OWNS_BEES'
    if nature == 'TAME_WILD':
        return case['original_owner'] + ('_RETAINS' if case.get('return_intent') else '_LOSES_TO_FIRST_OCCUPANT')
    if nature == 'DOMESTIC':
        if case.get('escaped'):
            return case['original_owner'] + ('_RETAINS_AND_THEFT' if case.get('taker_purpose') == 'PROFIT' else '_RETAINS')
        return case['original_owner'] + '_OWNS'
    raise ValueError('unknown nature')

examples = {
  'wild_escape': resolve({'nature':'WILD','captured':True,'escaped':True,'visible':False,'pursuit_easy':False,'original_owner':'ALICE','first_occupant':'BOB'}),
  'domestic_escape': resolve({'nature':'DOMESTIC','captured':True,'escaped':True,'visible':False,'pursuit_easy':False,'original_owner':'ALICE','first_occupant':'BOB','taker_purpose':'PROFIT'}),
  'wounded_unseized': resolve({'nature':'WILD','wounded':True,'pursuing':True,'captured':False,'original_owner':'ALICE','first_occupant':'BOB'}),
  'bee_swarm': resolve({'nature':'BEE','escaped':True,'visible':True,'pursuit_easy':True,'original_owner':'ALICE','first_occupant':'BOB'})
}
result = examples
